sys_script_include.script:
var OWS_Availability = Class.create();
OWS_Availability.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getAnswer: function() {
        var evStart = this.getParameter('sysparm_evStart');
        var evEnd = this.getParameter('sysparm_evEnd');
        var evSpace = this.getParameter('sysparm_evSpace');
		//Convert the Time in GMT Timezone
        var session = gs.getSession();
        var zoneName = session.getTimeZoneName();
        var evStartGMT = new GlideScheduleDateTime(evStart);
        evStartGMT.convertTimeZone(zoneName, "GMT");
        var evEndGMT = new GlideScheduleDateTime(evEnd);
        evEndGMT.convertTimeZone(zoneName, "GMT");
        //gs.info('Rocky OWS start - end - space - ' + evStart + evEnd + evSpace);
        var r = new sn_ws.RESTMessageV2('OWS WSD', 'Available');
        r.setStringParameterNoEscape('end', evEndGMT);
        r.setStringParameterNoEscape('start', evStartGMT);
        r.setStringParameterNoEscape('reservable_ids', evSpace);
        gs.info("Rocky Start Times:" + evStartGMT + "Rockey End:" + evEndGMT);
        var response = r.execute();
        var responseBody = response.getBody();
        var resultBody = JSON.parse(responseBody);
        gs.info('Rocky Response Body: ' + responseBody);
        /*var nameSpace = resultBody.result[0].name;
        var isAvailable = resultBody.result[0].is_available;
        gs.info('Rocky Response Body: ' + responseBody);
        gs.info('Rocky start');
        if (isAvailable) {
            gs.info(isAvailable);
            gs.info('Room ' + nameSpace + ' is available');
            var strAnswer = 'Room ' + nameSpace + ' is available';
            JSUtil.logObject(resultBody, "Parsed Response");
            //	isSpaceAvailable.push(strAnswer);
        } else {
            gs.info('Room ' + nameSpace + ' is not available');
            var strAnswer = 'Room ' + nameSpace + ' is not available';
            //	isSpaceAvailable.push(strAnswer);
        }
        gs.info('Rocky OWS: ' + strAnswer);

        return strAnswer;*/
        var returnobj = resultBody.result.map(function(room) {
            return {
                name: room.name,
                sys_id: room.sys_id,
                is_available: room.is_available
            };
        });
        //gs.info('Rocky Return Object: ' + JSON.stringify(returnobj));
        return JSON.stringify(returnobj);
    },

    type: 'OWS_Availability'
});
